#!/usr/bin/env python3
"""BoxProxy parity #12: the shipped baseline profile is generated by ART, not hand-written.

Host checks only (no Android build here):
- android-app/app/src/main/baseline-prof.txt is the retraced ART dump: GENERATED header, no
  wildcard rules, valid HRF syntax, thousands of method rules, and it covers the profiled journeys
  (cold start, 首页, 面板, 网络测试, 日志文件, 设置/基础代理配置/配置选择);
- the generation path stays compliant with the V20.93 gate: no new Gradle module, plugin or
  dependency (profileinstaller only), only :app in settings.gradle.kts;
- CI regenerates it on API 35 (HETU_BASELINE_PROFILE=1, R8 mapping artifact) and the release
  verifier decodes assets/dexopt/baseline.prof in the shipped APK against size/class/method floors;
- the retrace maps minified rules back to source names (inline groups, moved methods, residual
  signatures, synthesized classes dropped).
"""
import importlib.util
from pathlib import Path
import re
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]
PROFILE = ROOT / 'android-app/app/src/main/baseline-prof.txt'
APP = 'io/github/xgl34222220/hetu/'
RULE = re.compile(r'^(?:[HSP]+L[^;*\s]+;->[^\s(*]+\([^\s)*]*\)[^\s*]+|L[^;*\s]+;)$')
MIN_METHOD_RULES = 6000
MIN_APP_METHOD_RULES = 1000
MIN_CLASS_RULES = 2000


def load(name):
    spec = importlib.util.spec_from_file_location(name, ROOT / '.github/scripts' / (name + '.py'))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def rules():
    return [line for line in PROFILE.read_text().splitlines() if line.strip() and not line.startswith('#')]


class GeneratedProfileTest(unittest.TestCase):
    def test_profile_is_generated_not_hand_written(self):
        text = PROFILE.read_text()
        self.assertIn('GENERATED', text.splitlines()[0])
        self.assertIn('retrace_profile_continuity93.py', text)
        lines = rules()
        self.assertNotIn('*', '\n'.join(lines), 'Wildcard (hand-written) rules must not ship')
        bad = [line for line in lines if not RULE.match(line)]
        self.assertEqual(bad[:5], [], 'Invalid HRF rules')
        self.assertEqual(len(lines), len(set(lines)), 'Duplicate rules')

    def test_profile_is_large(self):
        lines = rules()
        methods = [line for line in lines if '->' in line]
        classes = [line for line in lines if '->' not in line]
        self.assertGreaterEqual(len(methods), MIN_METHOD_RULES)
        self.assertGreaterEqual(len(classes), MIN_CLASS_RULES)
        self.assertGreaterEqual(sum(1 for line in methods if APP in line), MIN_APP_METHOD_RULES)
        self.assertTrue(any(line.startswith('HS') for line in methods), 'No hot startup methods recorded')

    def test_profile_covers_profiled_journeys(self):
        text = '\n'.join(rules())
        for marker in JOURNEY_MARKERS:
            self.assertIn(marker, text, 'Journey not covered: ' + marker)

    def test_gate_compliant_generation_without_new_modules_or_dependencies(self):
        settings = (ROOT / 'android-app/settings.gradle.kts').read_text()
        self.assertEqual(re.findall(r'include\(([^)]*)\)', settings), ['":app"'])
        build = (ROOT / 'android-app/app/build.gradle.kts').read_text()
        root_build = (ROOT / 'android-app/build.gradle.kts').read_text()
        for forbidden in ('baselineprofile', 'benchmark', 'uiautomator'):
            self.assertNotIn(forbidden, build.lower() + root_build.lower())
        self.assertIn('implementation("androidx.profileinstaller:profileinstaller:1.4.1")', build)
        self.assertFalse((ROOT / 'android-app/baselineprofile').exists())
        self.assertFalse((ROOT / 'android-app/macrobenchmark').exists())

    def test_ci_regenerates_and_verifies_packaging(self):
        workflow = (ROOT / '.github/workflows/v2093-build.yml').read_text()
        self.assertIn("HETU_BASELINE_PROFILE: ${{ matrix.api == 35 && '1' || '' }}", workflow)
        self.assertIn('name: Hetu-V20.93-R8-mapping', workflow)
        self.assertIn('android-app/app/build/outputs/mapping/release/mapping.txt', workflow)
        self.assertIn('test_baseline_profile93.py', workflow)
        runner = (ROOT / '.github/scripts/run_hetu_emulator.py').read_text()
        self.assertIn('profile_release_continuity93.py', runner)
        capture = (ROOT / '.github/scripts/profile_release_continuity93.py').read_text()
        for token in ("'compile', '--reset'", 'androidx.profileinstaller.action.SAVE_PROFILE',
                      "'dump-profiles', '--dump-classes-and-methods'", 'retrace_profile_continuity93.py',
                      "'network-test'", "'logs'", "'config'", "'settings'", "'home'", "'cold-start'"):
            self.assertIn(token, capture)
        verify = load('verify_release_continuity93')
        self.assertGreater(verify.MIN_PROFILE_BYTES, 5020, 'Floor must exceed the old hand-written packaged profile')
        self.assertGreater(verify.MIN_PROFILE_HOT_METHODS, 15717)
        source = (ROOT / '.github/scripts/verify_release_continuity93.py').read_text()
        self.assertIn("decode_baseline_prof(profile_bytes)", source)
        self.assertIn("'assets/dexopt/baseline.prof' in names and 'assets/dexopt/baseline.profm' in names", source)

    def test_packaged_profile_decoder_rejects_corruption(self):
        import struct
        import zlib
        verify = load('verify_release_continuity93')
        key = b'classes.dex'
        ids = 8
        hot = struct.pack('<HH', 1, 0) + struct.pack('<HH', 2, 0)
        classes = struct.pack('<HH', 3, 1)
        bitmap = bytes([0b00000110, 0b00000010])
        body = struct.pack('<HHIII', len(key), 2, len(hot), 0, ids) + key + hot + classes + bitmap
        packed = zlib.compress(body)
        data = b'pro\x00010\x00' + bytes([1]) + struct.pack('<II', len(body), len(packed)) + packed
        dex = verify.decode_baseline_prof(data)[0]
        self.assertEqual((dex['classes'], dex['hotMethods'], dex['startupMethods'], dex['postStartupMethods']), (2, 2, 2, 1))
        with self.assertRaises(AssertionError):
            verify.decode_baseline_prof(b'pro\x00009\x00' + data[8:])
        broken = zlib.compress(body + b'\x00')
        with self.assertRaises(AssertionError):
            verify.decode_baseline_prof(b'pro\x00010\x00' + bytes([1]) + struct.pack('<II', len(body) + 1, len(broken)) + broken)

    def test_retrace_maps_minified_rules_to_source_names(self):
        retrace = load('retrace_profile_continuity93')
        mapping = '\n'.join((
            '# compiler: R8',
            'io.github.Foo -> a.b:',
            '# {"id":"sourceFile","fileName":"Foo.kt"}',
            '    java.lang.String name -> a',
            '    1:3:void <init>(io.github.Bar):10:12 -> <init>',
            '    4:4:int helper(int):20:20 -> a',
            '    4:4:int compute(io.github.Bar,int[]):30 -> a',
            '    5:7:void moved():1:3 -> b',
            '    5:7:void io.github.Other.real(long):5 -> b',
            '    8:9:void io.github.MergedKt.Screen(int):42:42 -> d',
            '    8:9:void Screen(int):0 -> d',
            '    void unboxed(java.lang.Integer) -> c',
            '    # {"id":"com.android.tools.r8.residualsignature","signature":"(I)V"}',
            'io.github.Bar -> a.c:',
            'io.github.Foo$$ExternalSyntheticLambda0 -> a.d:',
            '# {"id":"com.android.tools.r8.synthesized"}',
            '    void run() -> run',
            '    1:2:void io.github.Foo.lambda$0(int):0:0 -> invoke', ''))
        dumped = ['La/b;', 'HSPLa/b;-><init>(La/c;)V', 'HPLa/b;->a(La/c;[I)I', 'SPLa/b;->b(J)V', 'PLa/b;->c(I)V', 'HSPLa/b;->d(I)V',
                  'HSPLa/d;->run()V', 'HPLa/d;->invoke(I)V', 'La/d;', 'HSPLandroidx/x/Y;->go(La/c;)V']
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'mapping.txt'
            path.write_text(mapping)
            out, stats = retrace.retrace(dumped, path)
        self.assertEqual(out, ['Landroidx/x/Y;', 'HSPLandroidx/x/Y;->go(Lio/github/Bar;)V', 'Lio/github/Foo;',
                               'HSPLio/github/Foo;-><init>(Lio/github/Bar;)V', 'HPLio/github/Foo;->compute(Lio/github/Bar;[I)I',
                               'HPLio/github/Foo;->lambda$0(I)V',
                               'PLio/github/Foo;->unboxed(Ljava/lang/Integer;)V',
                               'Lio/github/MergedKt;', 'HSPLio/github/MergedKt;->Screen(I)V',
                               'Lio/github/Other;', 'SPLio/github/Other;->real(J)V'])
        self.assertEqual(stats['droppedSynthesized'], 2)


# Classes reached only through the profiled journeys (filled from the generated profile).
JOURNEY_MARKERS = (
    'L' + APP + 'HetuActivity;->onCreate(',                  # cold start
    'L' + APP + 'home/HomeScreenKt;->',                      # 首页
    'L' + APP + 'panel/Panel',                               # 面板
    'L' + APP + 'tools/Tools',                               # 工具
    'L' + APP + 'NetworkTestScreenKt;->NetworkTestScreen(',  # 工具 › 网络测试
    'L' + APP + 'ProxyLogViewerActivityKt;->',               # 工具 › 日志文件
    'L' + APP + 'SettingsScreenKt;->',                       # 设置
    'L' + APP + 'ProxyConfigLibrary;->',                     # 基础代理配置 › 配置选择
)


if __name__ == '__main__':
    unittest.main()
